def _fit(model, y):
    from scipy.optimize import least_squares
    k = 9 if model.regime else 7
    cache = [None, None]

    def components(theta):
        if cache[0] is None or not np.array_equal(cache[0], theta[:2]):
            cache[:] = [theta[:2].copy(), model.design(theta[:2])]
        return cache[1]

    def residual(theta, scale):
        return ((components(theta)[0] @ theta[2:] - y) / scale).ravel()

    def jac(theta, scale):
        design, grad, extra = components(theta)
        tau_grad = grad * theta[2:4]
        if extra is not None:
            tau_grad[:, :, 0] += extra @ theta[-2:]
        return (np.concatenate((tau_grad, design), axis=2) / np.asarray(scale)[..., None]).reshape(-1, k + 2)
    tmax = max(model.t.max(), model.dt.max())
    low, high = (np.log(min(model.dt.min(), model.t[model.t > 0].min()) / 25), np.log(tmax * 20))
    lb = np.r_[low, low, np.full(k, -np.inf)]
    ub = np.r_[high, high, np.full(k, np.inf)]
    if model.regime:
        seeds = tmax * np.array([[0.09, 0.48], [0.48, 0.09], [0.035, 0.29], [0.29, 0.035], [0.19, 1.3], [1.3, 0.19]])
    else:
        seeds = tmax * np.array([[0.09, 0.48], [0.035, 0.29], [0.19, 1.3]])

    def linear_seed(p, scale):
        design = model.design(p)[0]
        beta = np.linalg.lstsq((design / np.asarray(scale)[..., None]).reshape(-1, k), (y / scale).ravel(), rcond=None)[0]
        return np.r_[p, beta]

    def scales(r):
        return np.r_[np.full(y.shape[1] - 1, _mad(r[:, :-1])), _mad(r[:, -1])]
    seeds = np.log(seeds)
    seed = linear_seed(seeds[0], 1.0)
    scale = scales(residual(seed, 1.0).reshape(y.shape))
    warm = [least_squares(residual, linear_seed(p, scale), jac=jac, args=(scale,), bounds=(lb, ub), loss='soft_l1', max_nfev=100, x_scale='jac') for p in seeds[:2]]
    best_warm = min(warm, key=lambda r: r.cost).x
    scale = 1.25 * scales(residual(best_warm, 1.0).reshape(y.shape))
    starts = [best_warm] + [linear_seed(p, scale) for p in seeds]
    best = min((least_squares(residual, p, jac=jac, args=(scale,), bounds=(lb, ub), loss='cauchy', max_nfev=100, x_scale='jac') for p in starts), key=lambda r: r.cost).x
    logtau, hw = (best[:2].copy(), best[2:9].copy())
    rw = best[9:].copy() if model.regime else np.zeros(2)
    if not model.regime:
        order = np.argsort(logtau)
        logtau = logtau[order]
        hw[:2] = hw[:2][order]
    return (logtau, hw, rw)

def _history_affine(history, channel):
    for sweep in reversed(history):
        use = np.asarray(sweep['lab_id']) == channel
        x, y = (np.asarray(sweep[k])[use] for k in ('cmd_stress', 'true_stress'))
        if len(x) >= 2 and np.ptp(x) > 0:
            return _affine(x, y)
    return None

def _scales(residual):
    groups = (residual[:, :-1], residual[:, -1:])
    return np.array([max(1e-08, 1.4826 * np.median(np.abs(g - np.median(g)))) for g in groups])

def _clean_line(x, y):
    if len(x) < 3:
        return (np.ones(len(x), dtype=bool), False)
    errors = _line_candidates(x, y)
    if not len(errors):
        return (np.ones(len(x), dtype=bool), False)
    median = np.median(errors, axis=1)
    best = np.lexsort((np.sum(np.minimum(errors, 3.0), axis=1), median))[0]
    core = errors[best] <= max(8 * median[best], 1e-10)
    gain, bias = _affine(x[core], y[core])
    clean = np.abs(y - gain * x - bias) <= 3.0
    return (clean, not clean.all())
